    }

public static void onPlayerRespawn(Player oldPlayer, Player newPlayer, boolean alive) {
		if (!alive) {
			// At this point, the Forge capabilities have been invalidated and are no longer
			// accessible unless we do a hacky reviveCaps() call, see ForgeXplatImpl for details.
			KeptItemsComponent keeps = XplatAbstractions.INSTANCE.keptItemsComponent(oldPlayer, true);

			for (ItemStack stack : keeps.getStacks()) {
				ItemStack copy = stack.copy();
				copy.removeTagKey(TAG_KEEP);
				if (!newPlayer.getInventory().add(copy)) {
					newPlayer.spawnAtLocation(copy);
				}
			}
		}
	}

public static void keepDropsOnDeath(Player player) {
		List<ItemStack> keeps = new ArrayList<>();
		for (int i = 0; i < player.getInventory().getContainerSize(); i++) {
			ItemStack stack = player.getInventory().getItem(i);
			if (!stack.isEmpty() && stack.hasTag() && ItemNBTHelper.getBoolean(stack, TAG_KEEP, false)) {
				keeps.add(stack);
				player.getInventory().setItem(i, ItemStack.EMPTY);
			}
		}

		// The capabilities are not yet invalidated at this point, no need to do reviveCaps
		KeptItemsComponent data = XplatAbstractions.INSTANCE.keptItemsComponent(player, false);
		data.addAll(keeps);
	}

@Override
	public KeptItemsComponent keptItemsComponent(Player player, boolean reviveCaps) {
		if (reviveCaps) {
			// See the javadoc on reviveCaps for why this is necessary
			player.reviveCaps();
		}
		var ret = player.getCapability(ForgeInternalEntityCapabilities.KEPT_ITEMS).orElseThrow(IllegalStateException::new);
		if (reviveCaps) {
			player.invalidateCaps();
		}
		return ret;
	}

@SubscribeEvent(priority = EventPriority.HIGH)
	public static void onPlayerClone(net.minecraftforge.event.entity.player.PlayerEvent.Clone event)
	{
		if (!event.isWasDeath())
		{
			return;
		}

		EntityPlayer player = event.getEntityPlayer();
		EntityPlayer oldPlayer = event.getOriginal();

		if (player instanceof FakePlayer || player.world.getGameRules().getBoolean("keepInventory"))
		{
			return;
		}

		for (int i = 0; i < oldPlayer.inventory.mainInventory.size(); i++)
		{
			ItemStack stack = oldPlayer.inventory.mainInventory.get(i);

			if (stack.getItem() == FTBQuestsItems.BOOK && player.addItemStackToInventory(stack))
			{
				oldPlayer.inventory.mainInventory.set(i, ItemStack.EMPTY);
			}
		}
	}

