public void deserializeNBT(SNBTCompoundTag nbt) {
		int fileVersion = nbt.getInt("version");

		if (fileVersion != VERSION) {
			markDirty();
		}

		name = nbt.getString("name");
		locked = nbt.getBoolean("lock");
		rewardsBlocked = nbt.getBoolean("rewards_blocked");

		readLongLongMap(nbt, taskProgress, "task_progress");
		readLongLongMap(nbt, started, "started");
		readLongLongMap(nbt, completed, "completed");
		readLongLongMap(nbt, questRepeatableTime, "repeatable");
		readLongIntMap(nbt, completionCount, "completion_count");

		claimedRewards.clear();
		CompoundTag claimedRewardsNBT = nbt.getCompound("claimed_rewards");
		for (String s : claimedRewardsNBT.getAllKeys()) {
			claimedRewards.put(QuestKey.fromString(s), claimedRewardsNBT.getLong(s));
		}

		perPlayerData.clear();
		CompoundTag ppdTag = nbt.getCompound("player_data");
		for (String key : ppdTag.getAllKeys()) {
			try {
				UUID id = UUIDTypeAdapter.fromString(key);
				perPlayerData.put(id, PerPlayerData.fromNBT(ppdTag.getCompound(key), file));
			} catch (IllegalArgumentException e) {
				FTBQuests.LOGGER.error("ignoring invalid player ID {} while loading per-player data for team {}", key, teamId);
			}
		}
	}

private void readLongLongMap(CompoundTag tag, Long2LongMap map, String key) {
		map.clear();
		CompoundTag subTag = tag.getCompound(key);
		for (String subKey : subTag.getAllKeys()) {
			map.put(file.getID(subKey), subTag.getLong(subKey));
		}
	}

private void readLongIntMap(CompoundTag tag, Long2IntMap map, String key) {
		map.clear();
		CompoundTag subTag = tag.getCompound(key);
		for (String subKey : subTag.getAllKeys()) {
			map.put(file.getID(subKey), subTag.getInt(subKey));
		}
	}

@Override
    public void loadTag(ValueInput data) {
        super.loadTag(data);

        this.myPlan = null;
        this.myPattern = data.read("myPlan", ItemStack.OPTIONAL_CODEC).orElse(ItemStack.EMPTY);
        if (!this.myPattern.isEmpty()) {
            this.forcePlan = true;
            this.pushDirection = Direction.values()[data.getIntOr("pushDirection", 0)];
        } else {
            this.forcePlan = false;
        }

        this.upgrades.readFromNBT(data, "upgrades");
        this.recalculatePlan();
    }

public void readFromNBT(ValueInput input) {
        this.configManager.readFromNBT(input);
        this.patternInventory.readFromNBT(input, NBT_MEMORY_CARD_PATTERNS);
        this.priority = input.getIntOr(NBT_PRIORITY, 0);

        var unlockEventType = input.getByteOr(NBT_UNLOCK_EVENT, (byte) 0);
        this.unlockEvent = switch (unlockEventType) {
            case 0 -> null;
            case 1 -> UnlockCraftingEvent.REDSTONE_POWER;
            case 2 -> UnlockCraftingEvent.RESULT;
            case 3 -> UnlockCraftingEvent.REDSTONE_PULSE;
            default -> {
                LOG.error("Unknown unlock event type {} in NBT for pattern provider: {}", unlockEventType, input);
                yield null;
            }
        };
        if (this.unlockEvent == UnlockCraftingEvent.RESULT) {
            this.unlockStack = GenericStack.readTag(input.childOrEmpty(NBT_UNLOCK_STACK));
            if (this.unlockStack == null) {
                LOG.error("Could not load unlock stack for pattern provider from NBT: {}", input);
            }
        } else {
            this.unlockStack = null;
        }

        var sendListTag = input.childrenListOrEmpty("sendList");
        for (var sendListEntry : sendListTag) {
            var stack = GenericStack.readTag(sendListEntry);
            if (stack != null) {
                this.addToSendList(stack.what(), stack.amount());
            }
        }
        sendDirection = input.read("sendDirection", Direction.CODEC).orElse(null);

        this.returnInv.readFromTag(input.childrenListOrEmpty("returnInv"));
    }

