@Override
	public void deserializeNBT(HolderLookup.Provider registries, CompoundTag nbt) {
		slotTracker.clear();
		setSize(nbt.contains("Size", Tag.TAG_INT) ? nbt.getInt("Size") : stacks.size());
		ListTag tagList = nbt.getList("Items", Tag.TAG_COMPOUND);
		RegistryHelper.getRegistryAccess().ifPresent(registryAccess -> {
			for (int i = 0; i < tagList.size(); i++) {
				CompoundTag itemTag = tagList.getCompound(i);
				int slot = itemTag.getInt("Slot");
				if (slot >= 0 && slot < stacks.size()) {
					getStackFromNbt(slot, itemTag, registryAccess).ifPresent(stack -> stacks.set(slot, stack));
				}
			}
		});
		slotTracker.refreshSlotIndexesFrom(this);
		onLoad();
	}

private void deserializeNBT(CompoundTag tag, Supplier<MemorySettingsCategory> getMemorySettings) {
		if (!tag.contains(BASE_INDEXES_TAG)) {
			this.inventoryPartHandlers = new IInventoryPartHandler[]{new IInventoryPartHandler.Default(parent, parent.getSlots())};
			this.baseIndexes = new int[]{0};
			return;
		}

		baseIndexes = tag.getIntArray(BASE_INDEXES_TAG);
		inventoryPartHandlers = new IInventoryPartHandler[baseIndexes.length];
		ListTag partNamesTag = tag.getList("inventoryPartNames", Tag.TAG_STRING);
		int i = 0;
		for (Tag t : partNamesTag) {
			SlotRange slotRange = new SlotRange(baseIndexes[i], (i + 1 < baseIndexes.length ? baseIndexes[i + 1] : parent.getSlots()) - baseIndexes[i]);
			inventoryPartHandlers[i] = InventoryPartRegistry.instantiatePart(t.getAsString(), parent, slotRange, getMemorySettings);
			i++;
		}
	}

private void deserialize() {
		NBTHelper.getMap(categoryNbt, SLOT_FILTER_ITEMS_TAG, Integer::valueOf,
				(k, v) -> BuiltInRegistries.ITEM.getOptional(ResourceLocation.parse(v.getAsString()))).ifPresent(map -> map.forEach(this::addSlotItem));

		NBTHelper.getMap(categoryNbt, SLOT_FILTER_STACKS_TAG, Integer::valueOf,
				(k, v) -> v instanceof CompoundTag tag
						? RegistryHelper.getRegistryAccess().flatMap(registryAccess -> ItemStack.parse(registryAccess, tag))
						: Optional.empty())
				.ifPresent(map -> map.forEach(this::addSlotStack));
		ignoreNbt = NBTHelper.getBoolean(categoryNbt, IGNORE_NBT_TAG).orElse(true);
	}

@Override
	protected void loadAdditional(CompoundTag tag, HolderLookup.Provider registries) {
		super.loadAdditional(tag, registries);
		decorativeBlocks.deserializeNBT(registries, tag.getCompound("decorativeBlocks"));
		dyes.deserializeNBT(registries, tag.getCompound("dyes"));
		storageBlock.deserializeNBT(registries, tag.getCompound("storageBlock"));
		result = ItemStack.parse(registries, tag.getCompound("result")).orElse(ItemStack.EMPTY);
		slotMaterialInheritance.clear();
		ListTag inheritance = tag.getList("slotMaterialInheritance", Tag.TAG_COMPOUND);
		for (int i = 0; i < inheritance.size(); i++) {
			CompoundTag slotTag = inheritance.getCompound(i);
			slotMaterialInheritance.put(slotTag.getInt("slot"), slotTag.getBoolean("value"));
		}
		remainingParts.clear();
		ListTag remainingPartsTag = tag.getList("remainingParts", Tag.TAG_COMPOUND);
		for (int i = 0; i < remainingPartsTag.size(); i++) {
			CompoundTag partTag = remainingPartsTag.getCompound(i);
			ResourceLocation key = ResourceLocation.tryParse(partTag.getString("key"));
			if (key == null) {
				continue;
			}
			remainingParts.put(key, partTag.getInt("value"));
		}

		mainColor = tag.getInt("mainColor");
		accentColor = tag.getInt("accentColor");
	}

void loadCanonicalData(CompoundTag tag) {
		contentsNbt = tag.contains(CONTENTS_TAG) ? tag.getCompound(CONTENTS_TAG) : new CompoundTag();
		settingsNbt = tag.getCompound(SETTINGS_TAG);
		if (!tag.contains(SETTINGS_TAG)) {
			tag.put(SETTINGS_TAG, settingsNbt);
		}
		settingsHandler.reloadFrom(settingsNbt);
		numberOfInventorySlots = tag.getInt(NUMBER_OF_INVENTORY_SLOTS_TAG);
		numberOfUpgradeSlots = tag.getInt(NUMBER_OF_UPGRADE_SLOTS_TAG);
		sortBy = NBTHelper.getString(tag, SORT_BY_TAG).map(SortBy::fromName).orElse(SortBy.NAME);
		inventoryHandler = null;
		upgradeHandler = null;
		inventoryIOHandler = null;
	}

@Override
	protected void loadSlotNumbers(CompoundTag tag) {
		if (StorageBlockEntity.hasLinkedStorageEndpoint(storageStack)) {
			super.loadSlotNumbers(tag);
			return;
		}
		StorageBlockItem.getEntityWrapperTagFromStack(storageStack).ifPresentOrElse(wrapperTag -> {
			numberOfInventorySlots = wrapperTag.getInt(NUMBER_OF_INVENTORY_SLOTS_TAG);
			numberOfUpgradeSlots = wrapperTag.getInt(NUMBER_OF_UPGRADE_SLOTS_TAG);
			promoteSlotNumbersToDefaults();
			StorageBlockItem.setNumberOfInventorySlots(storageStack, numberOfInventorySlots);
			StorageBlockItem.setNumberOfUpgradeSlots(storageStack, numberOfUpgradeSlots);
		}, () -> {
			numberOfInventorySlots = StorageBlockItem.getNumberOfInventorySlots(storageStack);
			numberOfUpgradeSlots = StorageBlockItem.getNumberOfUpgradeSlots(storageStack);
		});
	}

@Override
    public void load(CompoundTag tag) {
        if (tag.contains(NBT_NETWORKS)) {
            ListTag networksTag = tag.getList(NBT_NETWORKS, Tag.TAG_COMPOUND);

            this.networks.clear();

            for (int i = 0; i < networksTag.size(); ++i) {
                CompoundTag networkTag = networksTag.getCompound(i);

                CompoundTag data = networkTag.getCompound(NBT_DATA);
                BlockPos pos = BlockPos.of(networkTag.getLong(NBT_POS));
                int type = networkTag.getInt(NBT_TYPE);

                INetwork network = new Network(level, pos, NetworkType.values()[type]);

                try {
                    network = network.readFromNbt(data);
                } catch (Throwable t) {
                    logger.error("Error while reading network", t);
                }

                this.networks.put(pos, network);
            }
        }
    }

@Override
    public void load(CompoundTag tag) {
        if (tag.contains(NBT_NODES)) {
            ListTag nodesTag = tag.getList(NBT_NODES, Tag.TAG_COMPOUND);

            this.nodes.clear();

            for (int i = 0; i < nodesTag.size(); ++i) {
                CompoundTag nodeTag = nodesTag.getCompound(i);

                ResourceLocation id = new ResourceLocation(nodeTag.getString(NBT_NODE_ID));
                CompoundTag data = nodeTag.getCompound(NBT_NODE_DATA);
                BlockPos pos = BlockPos.of(nodeTag.getLong(NBT_NODE_POS));

                INetworkNodeFactory factory = API.instance().getNetworkNodeRegistry().get(id);

                if (factory != null) {
                    INetworkNode node = null;

                    try {
                        node = factory.create(data, level, pos);
                    } catch (Throwable t) {
                        logger.error("Could not read network node", t);
                    }

                    if (node != null) {
                        this.nodes.put(pos, node);
                    }
                } else {
                    logger.warn("Factory for {} not found in network node registry", id);
                }
            }
        }
    }

