@Override
  public void deserialize(@Nonnull ValueInput input) {
    this.baseSize = input.getIntOr("BaseSize", this.getBaseSize());
    this.resize(input.getIntOr("Size", this.getSlots()));
    input.child("Stacks").ifPresent(stacks -> this.getStacks().deserialize(stacks));
    input.child("Cosmetics")
        .ifPresent(cosmetics -> this.getCosmeticStacks().deserialize(cosmetics));
    List<Boolean> renders = input.read("Renders", Codec.BOOL.listOf()).orElse(List.of());
    List<Boolean> currentRenders = this.getRenders();

    for (int i = 0; i < renders.size(); i++) {
      currentRenders.set(i, renders.get(i));
    }
    List<Boolean> activeStates = input.read("ActiveStates", Codec.BOOL.listOf()).orElse(List.of());
    List<Boolean> currentActiveStates = this.getActiveStates();

    for (int i = 0; i < activeStates.size(); i++) {
      currentActiveStates.set(i, activeStates.get(i));
    }
    this.cosmetic = input.getBooleanOr("Cosmetic", this.hasCosmetic());
    this.visible = input.getBooleanOr("Visible", this.isVisible());
    this.canToggleRender = input.getBooleanOr("ToggleRender", this.canToggleRendering());
    this.dropRule = input.read("DropRule", DropRule.CODEC).orElse(this.getDropRule());
    List<AttributeModifier> permanentModifiers =
        input.read("PermanentModifiers", AttributeModifier.CODEC.listOf()).orElse(List.of());

    for (AttributeModifier modifier : permanentModifiers) {
      this.addPermanentModifier(modifier);
    }
    List<AttributeModifier> modifiers =
        input.read("Modifiers", AttributeModifier.CODEC.listOf()).orElse(List.of());

    for (AttributeModifier modifier : modifiers) {
      this.addTransientModifier(modifier);
    }
  }

@SubscribeEvent
    public static void onPlayerClone(PlayerEvent.Clone event) {
        Player player = event.getEntity();
        Player original = event.getOriginal();

        original.reviveCaps();

        ILichdom capability2 = LichdomHelper.getCapability(original);

        player.getCapability(LichProvider.CAPABILITY)
                .ifPresent(lichdom ->
                        lichdom.setLichdom(capability2.getLichdom()));

        player.getCapability(LichProvider.CAPABILITY)
                .ifPresent(lichdom ->
                        lichdom.setLichMode(capability2.isLichMode()));

        player.getCapability(LichProvider.CAPABILITY)
                .ifPresent(lichdom ->
                        lichdom.setNightVision(capability2.nightVision()));

        player.getCapability(LichProvider.CAPABILITY)
                .ifPresent(lichdom ->
                        lichdom.setLichModeColor(capability2.lichModeColor()));

        ISoulEnergy capability3 = SEHelper.getCapability(original);

        player.getCapability(SEProvider.CAPABILITY)
                .ifPresent(soulEnergy ->
                        soulEnergy.setSEActive(capability3.getSEActive()));
        player.getCapability(SEProvider.CAPABILITY)
                .ifPresent(soulEnergy ->
                        soulEnergy.setSoulEnergy(capability3.getSoulEnergy()));
        player.getCapability(SEProvider.CAPABILITY)
                .ifPresent(soulEnergy ->
                        soulEnergy.setRecoil(capability3.getRecoil()));
        player.getCapability(SEProvider.CAPABILITY)
                .ifPresent(soulEnergy ->
                        soulEnergy.setArcaBlock(capability3.getArcaBlock()));
        player.getCapability(SEProvider.CAPABILITY)
                .ifPresent(soulEnergy ->
                        soulEnergy.setArcaBlockDimension(capability3.getArcaBlockDimension()));
        player.getCapability(SEProvider.CAPABILITY)
                .ifPresent(soulEnergy ->
                        soulEnergy.setArcaRevivePos(capability3.getArcaRevivePos()));
        player.getCapability(SEProvider.CAPABILITY)
                .ifPresent(soulEnergy ->
                        soulEnergy.setRestPeriod(capability3.getRestPeriod()));
        player.getCapability(SEProvider.CAPABILITY)
                .ifPresent(soulEnergy -> {
                    for (Research research : capability3.getResearch()){
                        soulEnergy.addResearch(research);
                    }
                });
        player.getCapability(SEProvider.CAPABILITY)
                .ifPresent(soulEnergy -> {
                    for (UUID uuid : capability3.grudgeList()){
                        soulEnergy.addGrudge(uuid);
                    }
                });
        player.getCapability(SEProvider.CAPABILITY)
                .ifPresent(soulEnergy -> {
                    for (UUID uuid : capability3.allyList()){
                        soulEnergy.addAlly(uuid);
                    }
                });
        player.getCapability(SEProvider.CAPABILITY)
                .ifPresent(soulEnergy -> {
                    for (EntityType<?> entityType : capability3.grudgeTypeList()){
                        soulEnergy.addGrudgeType(entityType);
                    }
                });
        player.getCapability(SEProvider.CAPABILITY)
                .ifPresent(soulEnergy -> {
                    for (EntityType<?> entityType : capability3.allyTypeList()){
                        soulEnergy.addAllyType(entityType);
                    }
                });
        player.getCapability(SEProvider.CAPABILITY)
                .ifPresent(soulEnergy -> {
                    soulEnergy.setBannerBaseColor(capability3.bannerBaseColor());
                });
        player.getCapability(SEProvider.CAPABILITY)
                .ifPresent(soulEnergy -> {
                    if (capability3.bannerPattern() != null) {
                        soulEnergy.setBannerPattern(capability3.bannerPattern());
                    }
                });
        player.getCapability(SEProvider.CAPABILITY)
                .ifPresent(soulEnergy ->
                        soulEnergy.setApostleWarned(capability3.apostleWarned()));
        player.getCapability(SEProvider.CAPABILITY)
                .ifPresent(soulEnergy ->
                        soulEnergy.setCooldowns(capability3.cooldowns()));
        player.getCapability(SEProvider.CAPABILITY)
                .ifPresent(soulEnergy ->
                        soulEnergy.setBottling(capability3.bottling()));;
        player.getCapability(SEProvider.CAPABILITY)
                .ifPresent(soulEnergy ->
                        soulEnergy.setCameraUUID(null));
        player.getCapability(SEProvider.CAPABILITY)
                .ifPresent(soulEnergy ->
                        soulEnergy.setMiningProgress(0));
        player.getCapability(SEProvider.CAPABILITY)
                .ifPresent(soulEnergy ->
                        soulEnergy.setMiningPos(null));

        IMisc capability4 = MiscCapHelper.getCapability(original);

        player.getCapability(MiscProvider.CAPABILITY)
                .ifPresent(misc ->
                        misc.setShields(capability4.shieldsLeft()));
        player.getCapability(MiscProvider.CAPABILITY)
                .ifPresent(misc ->
                        misc.setShieldTime(capability4.shieldTime()));
        player.getCapability(MiscProvider.CAPABILITY)
                .ifPresent(misc ->
                        misc.setShieldCool(capability4.shieldCool()));
        player.getCapability(MiscProvider.CAPABILITY)
                .ifPresent(misc ->
                        misc.setAmbientSoundTime(0));

    }

public void load(ListTag listTag){
        if (listTag != null) {
            listTag.forEach(tag -> {
                CompoundTag compoundTag = (CompoundTag) tag;
                Item item = Item.byId(compoundTag.getInt("Item"));
                int startTime = compoundTag.getInt("Time");
                int endTime = compoundTag.getInt("TotalTime");
                cooldowns.put(item, new CooldownInstance(startTime, endTime));
            });
        }
    }

