		if(tag.contains(TAG_CONNECTIONS)) {
			var c = tag.getByteArray(TAG_CONNECTIONS);
			for(int i = 0; i < c.length; i++) {
				connectionsCache[i] = ConnectionType.values()[c[i]];
			}
		}
	}

