@Override
	public void readData(NBTTagCompound nbt)
	{
		super.readData(nbt);
		items.clear();
		NBTTagList list = nbt.getTagList("items", Constants.NBT.TAG_COMPOUND);

		if (list.isEmpty())
		{
			ItemStack stack = ItemMissing.read(nbt.getTag("item"));

			if (!stack.isEmpty())
			{
				items.add(stack);
			}
			else
			{
				FTBQuests.LOGGER.warn("That's odd... Item is empty from tag " + nbt.getTag("item") + " in " + quest.chapter + "/" + quest + "/" + this);
			}
		}
		else
		{
			for (int i = 0; i < list.tagCount(); i++)
			{
				ItemStack stack = ItemMissing.read(list.get(i));

				if (!stack.isEmpty())
				{
					items.add(stack);
				}
				else
				{
					FTBQuests.LOGGER.warn("That's odd... Item is empty from tag " + list.get(i) + " in " + quest.chapter + "/" + quest + "/" + this);
				}
			}
		}

		if (items.isEmpty())
		{
			FTBQuests.LOGGER.warn("Item list is empty? That's not good... Task: " + quest.chapter + "/" + quest + "/" + this);
		}

		count = nbt.getLong("count");

		if (count < 1)
		{
			count = 1;
		}

		consumeItems = EnumTristate.read(nbt, "consume_items");
		ignoreDamage = nbt.getBoolean("ignore_damage");
		nbtMode = NBTMatchingMode.VALUES[nbt.getByte("ignore_nbt")];
		onlyFromCrafting = EnumTristate.read(nbt, "only_from_crafting");
	}

private void readData(NBTTagCompound nbt)
	{
		NBTTagCompound nbt1 = nbt.getCompoundTag("Tasks");

		for (String s : nbt1.getKeySet())
		{
			Task task = ServerQuestFile.INSTANCE.getTask(ServerQuestFile.INSTANCE.getID(s));

			if (task != null)
			{
				taskData.get(task.id).readProgress(nbt1.getLong(s));
			}
		}

		claimedTeamRewards.clear();

		for (int r : nbt.getIntArray("ClaimedTeamRewards"))
		{
			claimedTeamRewards.add(r);
		}

		claimedPlayerRewards.clear();

		nbt1 = nbt.getCompoundTag("ClaimedPlayerRewards");

		for (String s : nbt1.getKeySet())
		{
			UUID id = StringUtils.fromString(s);

			if (id != null)
			{
				int[] ar = nbt1.getIntArray(s);

				if (ar.length > 0)
				{
					IntOpenHashSet set = new IntOpenHashSet(ar.length);

					for (int r : ar)
					{
						set.add(r);
					}

					claimedPlayerRewards.put(id, set);
				}
			}
		}
	}

