@Override
    public void deserializeNBT(HolderLookup.Provider provider, CompoundTag nbt) {
        ListTag entries = nbt.getList(ID_MAP_KEY, 10);
        int nextId = nbt.getInt(NEXT_ID_KEY);
        for (Tag tag : entries) {
            try {
                CompoundTag compoundTag = (CompoundTag) tag;
                UUID uuid = compoundTag.getUUID(UUID_KEY);
                int pocketId = compoundTag.getInt(INT_ID_KEY);
                ids.put(uuid, pocketId);
            } catch (Exception e) {
                IronsSpellbooks.LOGGER.error("Failed to parse PocketDimensionManager id entry: {}: {}", tag, e.getMessage());
            }
        }
        this.nextId = nextId;
    }

@Override
    public void deserializeNBT(HolderLookup.Provider pRegistries, CompoundTag compoundTag) {
        if (compoundTag.contains("portalLookup")) {
            var portalLookupTag = (ListTag) compoundTag.get("portalLookup");
            if (portalLookupTag != null) {
                portalLookupTag.forEach(tag -> {
                    var portalLookupItem = (CompoundTag) tag;
                    var portalData = new PortalData();
                    portalData.deserializeNBT(pRegistries, portalLookupItem.getCompound("value"));
                    portalLookup.put(portalLookupItem.getUUID("key"), portalData);
                });
            }
        }
    }

@Override
    public void deserializeNBT(HolderLookup.Provider pRegistries, CompoundTag compoundTag) {
        ListTag offline = compoundTag.getList("OfflineSummons", Tag.TAG_COMPOUND);
        for (Tag tag : offline) {
            CompoundTag entry = (CompoundTag) tag;
            var uuid = entry.getUUID("summoner");
            ListTag summons = entry.getList("summons", Tag.TAG_COMPOUND);
            ArrayList<CompoundTag> summonsList = new ArrayList<>();
            summons.forEach(t -> summonsList.add((CompoundTag) t));
            offlineSummonersToSavedEntities.put(uuid, summonsList);
        }
    }

